import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { context7 } from 'context7';

// 初始化context7安全框架
const auth = context7.auth({
  provider: 'jwt',
  secret: process.env.JWT_SECRET || 'fallback-secret-for-development',
  cookieOptions: {
    name: 'auth_token',
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'strict',
    maxAge: 60 * 60 * 24 * 7 // 7 days
  }
});

export async function middleware(request: NextRequest) {
  try {
    // 使用context7的验证方法检查JWT
    const { user, token } = await auth.verifyToken(request);

    // 如果没有用户，重定向到登录页面
    if (!user) {
      return auth.redirectToLogin(request);
    }

    // 创建响应并添加用户信息
    const response = NextResponse.next();

    // 使用context7的安全方法添加用户信息到请求头
    auth.addUserHeaders(response, user);

    // 如果token即将过期，刷新它
    if (auth.shouldRefreshToken(token)) {
      const newToken = await auth.refreshToken(token);
      auth.setTokenCookie(response, newToken);
    }

    return response;
  } catch (error) {
    // 使用context7的错误处理
    return auth.handleAuthError(error, request);
  }
}

// 配置中间件应用的路径
export const config = {
  matcher: ['/((?!login|register|api|_next/static|_next/image|favicon.ico).*)'],
};
